.ddz-score-section {
  display: flex;
  align-items: center;
  gap: 16px;
  flex-wrap: wrap;
}

.ddz-gold-stat {
  font-size: 14px;
  font-weight: 800;
  color: #fbbf24;
  letter-spacing: 0.2px;
}

/* Middle Arena: Left Wing + Center Stage + Right Wing */
.ddz-arena {
  position: relative;
  z-index: 4;
  display: grid;
  grid-template-columns: 215px minmax(0, 1fr) 215px;
  gap: 12px;
  align-items: start;
  margin-top: 8px;
  min-height: 310px;
}

@media (max-width: 820px) {
  .ddz-arena {
    grid-template-columns: 1fr;
  }
}

.ddz-wing {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.ddz-wing.is-left {
  align-items: flex-start;
}

.ddz-wing.is-right {
  align-items: flex-end;
}

.ddz-wing-bubble-slot {
  min-height: 34px;
  display: flex;
  align-items: center;
}

.ddz-quote-bubble {
  padding: 6px 14px;
  border-radius: 999px;
  font-size: 12px;
  font-weight: 600;
  color: #e2e8f0;
  background: rgba(15, 23, 38, 0.85);
  border: 1px solid rgba(148, 163, 184, 0.25);
  box-shadow: 0 6px 18px rgba(0, 0, 0, 0.4);
  max-width: 220px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* Player Identity Badge Pill */
.ddz-player-pill {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  padding: 8px 14px 8px 10px;
  border-radius: 14px;
  background: rgba(15, 23, 36, 0.86);
  border: 1.5px solid rgba(255, 255, 255, 0.14);
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.45);
  backdrop-filter: blur(8px);
  min-width: 176px;
  transition: border-color 0.2s ease, box-shadow 0.2s ease;
}

.ddz-player-pill.is-compact {
  min-width: 162px;
  padding: 6px 12px 6px 8px;
}

.ddz-player-pill.is-turn {
  border-color: #fbbf24;
  box-shadow:
    0 0 0 2px rgba(251, 191, 36, 0.32),
    0 8px 24px rgba(0, 0, 0, 0.5);
}

.ddz-avatar-circle {
  width: 38px;
  height: 38px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  overflow: hidden;
  flex-shrink: 0;
}

.ddz-avatar-circle.is-peasant {
  background: radial-gradient(circle at 30% 30%, #3b82f6, #1d4ed8);
  border: 2px solid #93c5fd;
  color: #ffffff;
}

.ddz-avatar-circle.is-landlord {
  background: radial-gradient(circle at 30% 30%, #fbbf24, #b45309);
  border: 2px solid #fde68a;
  color: #1e293b;
}

.ddz-avatar-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.ddz-pill-info {
  display: flex;
  flex-direction: column;
  gap: 3px;
  min-width: 0;
}

.ddz-pill-name-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 6px;
}

.ddz-pill-name {
  font-size: 13px;
  font-weight: 700;
  color: #f8fafc;
  max-width: 108px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.ddz-mini-count {
  padding: 1px 6px;
  border-radius: 6px;
  font-size: 11px;
  font-weight: 800;
  background: rgba(255, 255, 255, 0.12);
  color: #fde68a;
}

.ddz-mini-count.is-alarm {
  background: rgba(239, 68, 68, 0.35);
  color: #fca5a5;
}

.ddz-role-pill {
  display: inline-block;
  align-self: flex-start;
  padding: 1px 8px;
  border-radius: 6px;
  font-size: 11px;
  font-weight: 700;
}

.ddz-role-pill.is-peasant {
  background: rgba(37, 99, 235, 0.32);
  border: 1px solid rgba(96, 165, 250, 0.55);
  color: #93c5fd;
}

.ddz-role-pill.is-landlord {
  background: rgba(217, 119, 6, 0.35);
  border: 1px solid rgba(251, 191, 36, 0.65);
  color: #fcd34d;
}

.ddz-role-pill.is-undecided {
  background: rgba(255, 255, 255, 0.1);
  color: #cbd5e1;
}

/* Curved 3D Vertical Side Card Back Fan */
.ddz-side-back-fan {
  position: relative;
  width: 132px;
  height: 230px;
  margin-top: 8px;
}

.ddz-side-back-fan.is-left {
  margin-left: 14px;
}

.ddz-side-back-fan.is-right {
  margin-right: 14px;
}

.ddz-blue-card-back {
  position: absolute;
  top: 0;
  left: 12px;
  width: 96px;
  height: 64px;
  border-radius: 8px;
  background:
    radial-gradient(circle at 50% 50%, rgba(96, 165, 250, 0.22), transparent 70%),
    linear-gradient(135deg, #1e40af 0%, #172554 100%);
  border: 1.5px solid rgba(96, 165, 250, 0.6);
  box-shadow: 0 6px 14px rgba(0, 0, 0, 0.55);
  display: grid;
  place-items: center;
}

.ddz-back-diamond {
  width: 12px;
  height: 12px;
  background: rgba(147, 197, 253, 0.32);
  transform: rotate(45deg);
  border-radius: 2px;
}

/* Open Fan when God View is active on side players */
.ddz-side-open-fan {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  max-width: 195px;
  margin-top: 6px;
}

/* Center Stage & Three-Directional Table Spots */
.ddz-center-felt {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  align-items: center;
  min-height: 280px;
  padding: 14px 8px;
}

.ddz-center-overlay {
  margin: auto;
  text-align: center;
  max-width: 360px;
  padding: 20px;
  border-radius: 18px;
  background: rgba(7, 14, 10, 0.65);
  border: 1px solid rgba(255, 255, 255, 0.12);
}

.ddz-gold-crown {
  color: #fbbf24;
}

.ddz-center-overlay h2 {
  margin: 8px 0 6px;
  font-size: 19px;
}

.ddz-center-overlay p {
  margin: 0 0 16px;
  font-size: 12.5px;
  color: #cbd5e1;
}

.ddz-stage-grid {
  width: 100%;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
  align-items: center;
  min-height: 160px;
}

.ddz-table-spot {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 6px;
  min-height: 82px;
}

.ddz-table-spot.is-left {
  justify-self: end;
  padding-right: 12px;
}

.ddz-table-spot.is-right {
  justify-self: start;
  padding-left: 12px;
}

.ddz-table-spot.is-bottom {
  margin-top: 6px;
}

.ddz-table-played-fan {
  display: flex;
  align-items: center;
  justify-content: center;
}

.ddz-table-played-fan .ddz-poker-card + .ddz-poker-card {
  margin-left: -22px;
}

.ddz-combo-badge {
  padding: 2px 10px;
  border-radius: 999px;
  font-size: 11px;
  font-weight: 700;
  color: #fde68a;
  background: rgba(0, 0, 0, 0.48);
  border: 1px solid rgba(251, 191, 36, 0.35);
}

.ddz-spot-chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 8px 20px;
  border-radius: 11px;
  font-size: 15px;
  font-weight: 700;
  box-shadow: 0 6px 16px rgba(0, 0, 0, 0.4);
}

.ddz-spot-chip.is-pass {
  background: rgba(8, 16, 12, 0.78);
  border: 1px solid rgba(255, 255, 255, 0.12);
  color: #94a3b8;
}

.ddz-spot-chip.is-gold {
  background: linear-gradient(180deg, #fbbf24 0%, #d97706 100%);
  color: #1e293b;
}

.ddz-spot-chip.is-thinking {
  font-size: 13px;
  background: rgba(245, 158, 11, 0.18);
  border: 1px solid rgba(251, 191, 36, 0.45);
  color: #fde68a;
}

.ddz-pulse-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: #fbbf24;
  animation: ddz-pulse 1.2s infinite ease-in-out;
}

@keyframes ddz-pulse {
  0%,
  100% {
    opacity: 0.35;
    transform: scale(0.85);
  }
  50% {
    opacity: 1;
    transform: scale(1.15);
  }
}

.ddz-winner-toast {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  padding: 8px 20px;
  margin-top: 8px;
  border-radius: 999px;
  background: rgba(15, 23, 36, 0.9);
  border: 1.5px solid #fbbf24;
  box-shadow: 0 10px 28px rgba(0, 0, 0, 0.55);
  font-size: 15px;
  color: #fef3c7;
}

.ddz-winner-mult {
  padding: 2px 8px;
  border-radius: 999px;
  background: rgba(245, 158, 11, 0.25);
  color: #fbbf24;
  font-weight: 800;
}

/* Authentic Dual-Index Poker Card Component */
.ddz-poker-card {
  position: relative;
  border-radius: 9px;
  background: linear-gradient(180deg, #ffffff 0%, #f8fafc 100%);
  border: 1px solid #cbd5e1;
  box-shadow: -3px 6px 14px rgba(0, 0, 0, 0.42);
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  padding: 6px 7px;
  user-select: none;
  flex-shrink: 0;
}

.ddz-poker-card.is-red {
  color: #dc2626;
}

.ddz-poker-card.is-black {
  color: #0f172a;
}

/* Card Sizes */
.ddz-poker-card.is-hole {
  width: 50px;
  height: 70px;
  padding: 4px 5px;
  border-radius: 7px;
}

.ddz-poker-card.is-table {
  width: 68px;
  height: 96px;
  padding: 6px 7px;
  border-radius: 9px;
}

.ddz-poker-card.is-hand {
  width: 76px;
  height: 110px;
  padding: 7px 8px;
  border-radius: 10px;
  transform: translateY(var(--fan-y, 0px)) rotate(var(--fan-angle, 0deg));
  transform-origin: 50% 125%;
  transition: transform 0.16s cubic-bezier(0.2, 0.8, 0.2, 1),
    box-shadow 0.16s ease, border-color 0.16s ease;
}

.ddz-poker-card.is-mini {
  width: 40px;
  height: 56px;
  padding: 3px 4px;
  border-radius: 6px;
}

.ddz-poker-card.is-interactive {
  cursor: pointer;
}

.ddz-poker-card.is-hand.is-interactive:hover:not(:disabled) {
  transform: translateY(calc(var(--fan-y, 0px) - 12px))
    rotate(var(--fan-angle, 0deg));
  border-color: #f59e0b;
}

.ddz-poker-card.is-hand.is-selected {
  transform: translateY(calc(var(--fan-y, 0px) - 24px))
    rotate(var(--fan-angle, 0deg)) !important;
  background: #fffbeb;
  border: 2px solid #f59e0b;
  box-shadow:
    0 0 0 3px rgba(245, 158, 11, 0.32),
    -4px 14px 24px rgba(0, 0, 0, 0.55);
}

.ddz-card-corner {
  display: flex;
  flex-direction: column;
  align-items: center;
  line-height: 0.95;
  width: fit-content;
}

.ddz-card-corner.is-bottom {
  align-self: flex-end;
  transform: rotate(180deg);
}

.ddz-poker-card.is-mini .ddz-card-corner.is-bottom,
.ddz-poker-card.is-hole .ddz-card-corner.is-bottom {
  display: none;
}

.ddz-card-rank {
  font-size: 17px;
  font-weight: 850;
  letter-spacing: -0.6px;
}

.ddz-poker-card.is-joker .ddz-card-rank {
  font-size: 9px;
  letter-spacing: 0px;
}

.ddz-poker-card.is-hole .ddz-card-rank {
  font-size: 13px;
}

.ddz-poker-card.is-mini .ddz-card-rank {
  font-size: 11px;
}

.ddz-card-suit {
  font-size: 12px;
  margin-top: 2px;
}

.ddz-poker-card.is-hole .ddz-card-suit,
.ddz-poker-card.is-mini .ddz-card-suit {
  font-size: 10px;
}

.ddz-card-pip {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  font-size: 28px;
  line-height: 1;
  opacity: 0.92;
  pointer-events: none;
}

.ddz-poker-card.is-hole .ddz-card-pip {
  font-size: 20px;
  top: 58%;
}

.ddz-poker-card.is-mini .ddz-card-pip {
  font-size: 15px;
  top: 60%;
}

/* Bottom Zone: Action Pill Bar + Arched Overlapping Poker Hand Fan */
.ddz-bottom-zone {
  position: relative;
  z-index: 6;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 14px;
  margin-top: 4px;
}

.ddz-bottom-hud {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 14px;
  flex-wrap: wrap;
}

.ddz-action-row {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  flex-wrap: wrap;
}

.ddz-pill-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  height: 40px;
  padding: 0 22px;
  border-radius: 11px;
  font-size: 14px;
  font-weight: 750;
  cursor: pointer;
  transition: all 0.16s ease;
  box-shadow: 0 6px 16px rgba(0, 0, 0, 0.4);
}

.ddz-pill-btn:disabled {
  opacity: 0.45;
  cursor: default;
}

.ddz-pill-btn.is-pass {
  background: linear-gradient(180deg, #5c2824 0%, #431c19 100%);
  border: 1.5px solid #991b1b;
  color: #fca5a5;
}

.ddz-pill-btn.is-pass:hover:not(:disabled) {
  filter: brightness(1.12);
}

.ddz-pill-btn.is-hint {
  background: linear-gradient(180deg, #27473c 0%, #1b332b 100%);
  border: 1.5px solid #4ade80;
  color: #ecfdf5;
}

.ddz-pill-btn.is-hint:hover:not(:disabled) {
  filter: brightness(1.12);
}

.ddz-pill-btn.is-gold {
  background: linear-gradient(180deg, #fbbf24 0%, #b45309 100%);
  border: 1.5px solid #fde68a;
  color: #1e293b;
}

.ddz-pill-btn.is-gold:disabled {
  background: rgba(120, 83, 24, 0.55);
  border-color: rgba(217, 119, 6, 0.35);
  color: rgba(254, 243, 199, 0.55);
}

.ddz-pill-btn.is-gold:hover:not(:disabled) {
  filter: brightness(1.08);
}

.ddz-talk-input {
  width: 210px;
  height: 36px;
  padding: 0 12px;
  border-radius: 10px;
  font-size: 12px;
  background: rgba(7, 14, 10, 0.72);
  border: 1px solid rgba(255, 255, 255, 0.16);
  color: #f8fafc;
  outline: none;
}

.ddz-arch-fan {
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 26px 24px 12px;
  min-height: 148px;
  max-width: 100%;
  overflow-x: auto;
}

.ddz-arch-fan .ddz-poker-card + .ddz-poker-card {
  margin-left: -30px;
}

.ddz-spectator-mask {
  padding: 20px 28px;
  border-radius: 14px;
  background: rgba(7, 14, 10, 0.65);
  border: 1px dashed rgba(255, 255, 255, 0.18);
  color: #94a3b8;
  font-size: 13px;
}

/* Modal */
.ddz-modal-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.68);
  display: grid;
  place-items: center;
  z-index: 60;
  padding: 16px;
}

.ddz-modal {
  width: 100%;
  max-width: 440px;
  padding: 22px;
  border-radius: 16px;
  background: #111827;
  border: 1px solid rgba(255, 255, 255, 0.14);
  box-shadow: 0 20px 48px rgba(0, 0, 0, 0.6);
  color: #f8fafc;
}

.ddz-modal-head h3 {
  margin: 0 0 6px;
  font-size: 18px;
}

.ddz-modal-head p {
  margin: 0 0 16px;
  font-size: 12.5px;
  color: #94a3b8;
}

.ddz-slot-list {
  display: flex;
  flex-direction: column;
  gap: 12px;
  margin-bottom: 16px;
}

.ddz-slot-row {
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.ddz-slot-label {
  font-size: 12px;
  font-weight: 600;
  color: #cbd5e1;
}

.ddz-slot-select {
  height: 38px;
  padding: 0 10px;
  border-radius: 9px;
  border: 1px solid rgba(255, 255, 255, 0.16);
  background: #1e293b;
  color: #f8fafc;
}

.ddz-slot-alert {
  padding: 8px 12px;
  margin-bottom: 14px;
  border-radius: 8px;
  font-size: 12px;
  background: rgba(127, 29, 29, 0.45);
  color: #fca5a5;
}

.ddz-modal-actions {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
}

